  unsigned int color;
  node *parent;
  node *left;
  node *right;
  ref_t *value;
};
struct tree {
  node *header;
  unsigned int count;
};
struct iterator {
  node *n;
  iterator &operator++() {
    if (n->right) {
      n = n->right;
      while (n->left) n = n->left;
    } else {
      node *p = n->parent;
      while (n == p->right) { n = p; p = p->parent; }
      if (n->right != p) n = p;
    }
    return *this;
  }
  ref_t *operator*() const { return n->value; }
  bool operator!=(const iterator &x) const { return n != x.n; }
};
