struct bank { tree refs_by_label; tree refs_by_ptr; };
extern "C" void destroy_bank(bank *, int) __asm__("_$_t13instance_bank1Z7cg_mesh");
void destroy_bank(bank *self, int flags) {
  iterator i;
  for (i.n = self->refs_by_label.header->left;
       i.n != self->refs_by_label.header; ++i) {
    ref_t *r = *i;
    debug_print("WARNING: Unreleased instance.");
    delete r;
  }
  tree *p = &self->refs_by_ptr;
  if (p->count) {
    erase_ptr(p, p->header->left);
    p->header->left = p->header;
    p->header->parent = 0;
    p->header->right = p->header;
    p->count = 0;
  }
  arch_free(p->header);
  tree *l = &self->refs_by_label;
  if (l->count) {
    erase_label(l, l->header->left);
    l->header->left = l->header;
    l->header->parent = 0;
    l->header->right = l->header;
    l->count = 0;
  }
  arch_free(l->header);
  if (flags & 1) builtin_delete(self);
}
